tools.example:
x = 0:0.01:pi;
y = sin(x);
trapz(x, y)
trapz(0.01, y)
A = [1 2; 3 4; 5 6];
trapz(A)

t = 0:0.01:2;
a = 9.81 * ones(size(t));
v = cumtrapz(t, a);
x = cumtrapz(t, v);
plot(t, v, t, x)
[x(end) 0.5*9.81*4]

x = -2:0.2:2;
y = x.^3;
dy = gradient(y, 0.2);
plot(x, dy, x, 3*x.^2)
[X, Y] = meshgrid(-2:0.25:2);
Z = X.*exp(-X.^2 - Y.^2);
[U, V] = gradient(Z, 0.25);
quiver(X, Y, U, V)

rosen = @(v) 100*(v(2) - v(1)^2)^2 + (1 - v(1))^2;
[x, fval, flag, out] = fminsearch(rosen, [-1.2 1]);
x
fval
out.iterations
opts = optimset('TolX', 1e-10, 'Display', 'iter');

opts = optimset('Display', 'iter', 'TolX', 1e-10);
x = fminbnd(@(x) cos(x), 0, 2*pi, opts);
optimget(opts, 'TolX')
opts2 = optimset(opts, 'MaxIter', 500);

f = @(t, y) -2*y + sin(t);
opts = odeset('RelTol', 1e-3);
[t, y] = ode23(f, [0 10], 1, opts);
plot(t, y)
numel(t)

mu = 1;
twoBody = @(t, s) [s(3); s(4); -mu*s(1)/norm(s(1:2))^3; -mu*s(2)/norm(s(1:2))^3];
opts = odeset('RelTol', 1e-12, 'AbsTol', 1e-14);
[t, s] = ode113(twoBody, [0 20], [1; 0; 0; 1], opts);
plot(s(:,1), s(:,2)); axis equal

f = @(t, y) [-1000*y(1) + y(2); y(1) - y(2)];
J = [-1000 1; 1 -1];
opts = odeset('Jacobian', J, 'RelTol', 1e-4);
[t, y] = ode23s(f, [0 5], [1; 0], opts);
semilogy(t, abs(y))

M = [1 0; 0 0];
f = @(t, y) [y(2); y(1) + y(2) - sin(t)];
opts = odeset('Mass', M, 'MassSingular', 'yes');
[t, y] = ode23t(f, [0 10], [0; 0], opts);
plot(t, y(:,1))

res = @(t, y, yp) yp - (-y + sin(t));
[y0, yp0] = decic(res, 0, 1, 1, 0, []);
[t, y] = ode15i(res, [0 10], y0, yp0);
plot(t, y)

f = @(t, y) [y(2); -y(1)];
opts = odeset('RelTol', 1e-12, 'AbsTol', 1e-14);
[t, y] = ode78(f, [0 100], [1; 0], opts);
max(abs(y(:,1) - cos(t)))

f = @(t, y) [y(2); -sin(y(1))];
opts = odeset('RelTol', 1e-13, 'AbsTol', 1e-15);
[t, y] = ode89(f, [0 50], [pi/3; 0], opts);
energy = 0.5*y(:,2).^2 - cos(y(:,1));
max(abs(energy - energy(1)))

bounce = @(t, y) [y(2); -9.81];
evt = @(t, y) deal(y(1), 1, -1);
opts = odeset('Events', evt, 'RelTol', 1e-8, 'MaxStep', 0.01);
[t, y, te, ye, ie] = ode45(bounce, [0 5], [10; 0], opts);
te

F = ode(ODEFcn=@(t,y,p) p*y, InitialValue=1, Parameters=-0.5);
S = solve(F, 0, 10);
plot(S.Time, S.Solution)
F.Parameters = -2;
S2 = solve(F, 0, 10);
fcn = solutionFcn(F, 0, 10);
fcn(3.7)

odefun = @(x, y) [y(2); -abs(y(1))];
bcfun = @(ya, yb) [ya(1); yb(1) + 2];
solinit = bvpinit(linspace(0, 4, 10), [1 0]);
sol = bvp4c(odefun, bcfun, solinit);
x = linspace(0, 4, 200);
plot(x, deval(sol, x, 1))

odefun = @(x, y) [y(2); -y(1)];
bcfun = @(ya, yb) [ya(1); yb(1) - 1];
solinit = bvpinit(linspace(0, pi/2, 20), [0 1]);
sol = bvp5c(odefun, bcfun, solinit, bvpset('RelTol', 1e-10));
deval(sol, pi/4, 1)

solinit = bvpinit(linspace(0, 1, 10), [0 1]);
guess = @(x) [sin(pi*x); pi*cos(pi*x)];
solinit2 = bvpinit(linspace(0, 1, 20), guess);
solinit3 = bvpinit(linspace(0,1,5), [0 0], 1);

pdefun = @(x,t,u,dudx) deal(1, dudx, 0);
icfun = @(x) sin(pi*x);
bcfun = @(xl,ul,xr,ur,t) deal(ul, 0, ur, 0);
x = linspace(0, 1, 40);
t = linspace(0, 0.5, 20);
sol = pdepe(0, pdefun, icfun, bcfun, x, t);
surf(x, t, sol(:,:,1))

ddefun = @(t, y, Z) -y + 2*Z(1);
sol = dde23(ddefun, 1, 0.5, [0 20]);
plot(sol.x, sol.y)
deval(sol, 10)

delays = @(t, y) t - 1 - 0.5*abs(sin(t));
ddefun = @(t, y, Z) -y + Z(1);
sol = ddesd(ddefun, delays, 1, [0 15]);
plot(sol.x, sol.y)
